    18	
    19	// Per-variant padding. '2xl' and '3xl' are the named spacing keys behind
    20	// --zimm-scale-800 (32px) and --zimm-scale-1000 (40px) — see
    21	// foundation/zimmTokens.ts, which defines both aliases from those keys. Using the
    22	// semantic keys keeps this at level 2 of the overrideStyling.md hierarchy rather
    23	// than reaching for the numeric vars.
    24	//
    25	// Keyed per variant because all three treatments share one wrapper: breadcrumbs
    26	// needs a 40px right inset where the other two keep 80px, so a single shared value
    27	// can no longer express every side.
    28	const PADDING = {
    29	  // Breadcrumbs: 40px horizontal, 32px vertical.
    30	  breadcrumbs: { pt: '2xl', pb: '2xl', pl: '3xl', pr: '3xl' },
    31	  'recently-viewed': { pt: 'xs', pb: '2xl', pl: '3xl', pr: '5xl' },
    32	  'section-title': { pt: 'xs', pb: '2xl', pl: '3xl', pr: '5xl' },
    33	} satisfies Record<PageToolbarVariant, { pt: string; pb: string; pl: string; pr: string }>;
    34	
    35	/**
    36	 * Structural wrapper for breadcrumb, recently-viewed, and section-title treatments.
    37	 * Port of the handover `zimm-page-toolbar` element.
    38	 */
    39	const ZimmPageToolbar = (props: ZimmPageToolbarProps) => {
    40	  return (
    41	    <Box {...PADDING[props.variant]} backgroundColor="background.07">
    42	      {props.variant === 'recently-viewed' || props.variant === 'section-title' ? (
