     1	import React from 'react';
     2	import { useParams } from 'react-router-dom';
     3	import { useIntl } from 'react-intl';
     4	import { useCategory, useProduct } from '@salesforce/commerce-sdk-react';
     5	import { Box, Skeleton, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
     6	import PdpProductInfo from '../../components/pdpProductInfo';
     7	import type { BreadcrumbCategory } from '../../components/breadcrumb';
     8	import Breadcrumb from '../../components/breadcrumb';
     9	import ZimmPageToolbar from '../../components/ui-kits/atoms/zimmPageToolbar';
    10	import { extractModelLine } from '../../utils/productData';
    11	import type { ProductWithSizeFit } from '../../types';
    12	
    13	// Provisional — no matching zimm token; pending designer sign-off.
    14	export const PDP_OPTIONS_COLUMN_WIDTH = '360px';
    15	
    16	
    17	const ProductDetail = () => {
    18	  const { productId } = useParams<{ productId: string }>();
    19	  const intl = useIntl();
    20	
    21	  const {
    22	    data: product,
    23	    isLoading,
    24	    error,
    25	  } = useProduct({ parameters: { id: productId } }, { enabled: Boolean(productId) });
    26	
    27	  // Enabled only after product loads — category ID is not known until then.
    28	  const { data: category, isError: isCategoryError } = useCategory(
    29	    { parameters: { id: product?.primaryCategoryId ?? null, levels: 1 } },
    30	    { enabled: Boolean(product?.primaryCategoryId) },
    31	  );
    32	
    33	  // ancestors (parentCategoryTree) + leaf category → full breadcrumb path.
    34	  // If the category call fails, degrades to an empty path (Home > Product Name only).
    35	  const breadcrumbCategories =
    36	    !category || isCategoryError
    37	      ? []
    38	      : (category.parentCategoryTree ?? []).filter(
    39	          (p): p is BreadcrumbCategory => Boolean(p.id) && Boolean(p.name),
    40	        );
    41	
    42	  const formattedPrice =
    43	    product?.price != null && product?.currency
    44	      ? intl.formatNumber(product.price, { style: 'currency', currency: product.currency })
    45	      : '';
    46	
    47	  return (
    48	    <Box className="sf-product-detail-page" data-testid="product-details-page">
    49	      <Box
    50	        display="grid"
    51	        gridTemplateColumns={{ base: '1fr', md: `1fr ${PDP_OPTIONS_COLUMN_WIDTH}` }}
    52	        columnGap={{ base: 0, md: 'var(--zimm-scale-4500)' }}
    53	        alignItems="start"
    54	      >
    55	        {/* Gallery column — images out of scope, placeholder maintains layout */}
    56	        <Box minW={0} backgroundColor="background.02" aspectRatio={{ base: '3/4', md: '49/60' }} />
    57	
    58	        {/* Options column */}
    59	        <Box
    60	          minW={0}
    61	          pl={{ base: 'var(--zimm-scale-800)', md: 0 }}
    62	          pr={{ base: 'var(--zimm-scale-800)', md: 'var(--zimm-scale-3500)' }}
    63	          pt={{ base: 'var(--zimm-scale-400)', md: 0 }}
    64	        >
    65	          {error ? (
    66	            <Text color="status.error">Unable to load product information.</Text>
    67	          ) : isLoading ? (
    68	            <>
    69	              <Skeleton height="var(--zimm-scale-800)" mb="m" />
    70	              <Skeleton height="var(--zimm-scale-500)" mb="xl" width="40%" />
    71	              <Skeleton height="var(--zimm-scale-5xl)" />
    72	            </>
    73	          ) : (
    74	            <PdpProductInfo
    75	              name={product?.name ?? ''}
    76	              price={formattedPrice}
    77	              description={product?.shortDescription || product?.longDescription}
    78	              modelInfo={extractModelLine((product as ProductWithSizeFit | undefined)?.c_sizeFit)}
    79	              styleCode={product?.id}
    80	            />
    81	          )}
    82	        </Box>
    83	      </Box>
    84	
    85	      <ZimmPageToolbar variant="breadcrumbs">
    86	        <Breadcrumb categories={breadcrumbCategories} currentPage={product?.name} />
    87	      </ZimmPageToolbar>
    88	    </Box>
    89	  );
    90	};
